CREATE TABLE crossings ( key TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK (revision > 0), payload_json TEXT NOT NULL CHECK (json_valid(payload_json)), updated_at TEXT NOT NULL );
CREATE TABLE normative ( key TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK (revision > 0), payload_json TEXT NOT NULL CHECK (json_valid(payload_json)), updated_at TEXT NOT NULL );
CREATE TABLE revisions ( kind TEXT NOT NULL CHECK (kind IN ('crossings', 'normative')), key TEXT NOT NULL, revision INTEGER NOT NULL, payload_json TEXT NOT NULL CHECK (json_valid(payload_json)), updated_at TEXT NOT NULL, PRIMARY KEY (kind, key, revision) );
CREATE TABLE pu66_sources ( sha256 TEXT PRIMARY KEY, original_name TEXT NOT NULL, workbook BLOB NOT NULL );
CREATE TABLE pu66_cards ( key TEXT PRIMARY KEY, revision INTEGER NOT NULL, payload_json TEXT NOT NULL CHECK (json_valid(payload_json)), source_sha256 TEXT NOT NULL REFERENCES pu66_sources(sha256), updated_at TEXT NOT NULL );
CREATE TABLE pu66_revisions ( key TEXT NOT NULL, revision INTEGER NOT NULL, payload_json TEXT NOT NULL CHECK (json_valid(payload_json)), source_sha256 TEXT NOT NULL REFERENCES pu66_sources(sha256), updated_at TEXT NOT NULL, PRIMARY KEY (key, revision) );
CREATE TABLE signs ( code TEXT PRIMARY KEY, numbered_png BLOB NOT NULL, plain_png BLOB NOT NULL, numbered_sha256 TEXT NOT NULL, plain_sha256 TEXT NOT NULL, zip_sha256 TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, revision INTEGER NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE project_drafts ( id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK (revision > 0), scheme_json TEXT NOT NULL CHECK (json_valid(scheme_json)), reference_id TEXT NOT NULL, location_text TEXT NOT NULL, template_code TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE project_revisions ( id TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), scheme_json TEXT NOT NULL CHECK (json_valid(scheme_json)), updated_at TEXT NOT NULL, PRIMARY KEY (id, revision), FOREIGN KEY (id) REFERENCES project_drafts(id) );
CREATE TABLE pu66_verifications ( id INTEGER PRIMARY KEY AUTOINCREMENT, key TEXT NOT NULL, card_revision INTEGER NOT NULL CHECK (card_revision > 0), verified_at TEXT NOT NULL, verified_by TEXT NOT NULL, recorded_at TEXT NOT NULL, FOREIGN KEY (key, card_revision) REFERENCES pu66_revisions(key, revision) );
CREATE INDEX pu66_verifications_by_card ON pu66_verifications(key, card_revision, id);
CREATE TABLE sign_catalog_batches ( id INTEGER PRIMARY KEY AUTOINCREMENT, document_code TEXT NOT NULL, edition TEXT NOT NULL, pdf_sha256 TEXT, zip_sha256 TEXT NOT NULL, sign_count INTEGER NOT NULL, imported_at TEXT NOT NULL );
CREATE TABLE sign_active ( code TEXT PRIMARY KEY REFERENCES signs(code), batch_id INTEGER REFERENCES sign_catalog_batches(id) );
CREATE TABLE sign_revisions ( code TEXT NOT NULL, revision INTEGER NOT NULL, numbered_png BLOB NOT NULL, plain_png BLOB NOT NULL, numbered_sha256 TEXT NOT NULL, plain_sha256 TEXT NOT NULL, zip_sha256 TEXT NOT NULL, batch_id INTEGER REFERENCES sign_catalog_batches(id), active INTEGER NOT NULL CHECK (active IN (0, 1)), updated_at TEXT NOT NULL, PRIMARY KEY (code, revision) );
CREATE TABLE project_sources ( sha256 TEXT PRIMARY KEY, original_json TEXT NOT NULL );
CREATE TABLE project_recovery ( session_id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK (version > 0), scheme_json TEXT NOT NULL CHECK (json_valid(scheme_json)), base_revision INTEGER CHECK (base_revision >= 0), details_json TEXT CHECK (details_json IS NULL OR json_valid(details_json)), placement_json TEXT CHECK (placement_json IS NULL OR json_valid(placement_json)), file_name TEXT NOT NULL, reference_id TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE pu66_key_aliases (old_key TEXT PRIMARY KEY, new_key TEXT);
INSERT INTO "crossings" ("key", "revision", "payload_json", "updated_at") VALUES ('TEST-001', 1, '{"referenceId":"TEST-001","railwayLocation":"Учебный участок","roadName":"Условная дорога","roadOwner":"Учебный владелец","cardReference":"Вымышленная карточка","cardUpdatedAt":"2026-09-26","verifiedAt":"","notes":"Без реальных данных"}', '2026-09-26T12:00:00.000Z');
INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('odm-218-6-019-2016-b33', 1, '{"id":"odm-218-6-019-2016-b33","documentCode":"ОДМ 218.6.019-2016","edition":"2016","clause":"Приложение Б, рисунок Б.33, с. 100","description":"Пример схемы для двухполосной дороги при краткосрочных работах; подпись говорит о зоне более 30 м, рисунок содержит обозначение min 30.","application":"Правило проекта для длины от 30 м. Случай ровно 30 м требует предметной сверки из-за расхождения подписи и размерного обозначения.","sourceUrl":"https://rosavtodor.gov.ru/about/upravlenie-fda/upravlenie-nauchno-tekhnicheskikh-issledovaniy--i-informatsionnykh-tekhnologiy/tekhnicheskoe-regulirovanie/otraslevye-dorozhnye-metodicheskie-dokumenty/14520","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('odm-218-6-019-2016-b34', 1, '{"id":"odm-218-6-019-2016-b34","documentCode":"ОДМ 218.6.019-2016","edition":"2016","clause":"Приложение Б, рисунок Б.34, с. 101","description":"Пример схемы для двухполосной дороги при краткосрочных работах; подпись говорит о зоне менее 30 м, рисунок содержит обозначение max 30.","application":"Правило проекта для длины менее 30 м. Условия регулирования движения по интенсивности и видимости следует сверять отдельно.","sourceUrl":"https://rosavtodor.gov.ru/about/upravlenie-fda/upravlenie-nauchno-tekhnicheskikh-issledovaniy--i-informatsionnykh-tekhnologiy/tekhnicheskoe-regulirovanie/otraslevye-dorozhnye-metodicheskie-dokumenty/14520","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('gost-r-52289-2019', 1, '{"id":"gost-r-52289-2019","documentCode":"ГОСТ Р 52289-2019","edition":"2019; изменения № 1 и № 2 подлежат сверке","clause":"Раздел 5, в том числе 5.1.19 и 5.2.27","description":"Правила применения технических средств организации дорожного движения; конкретные параметры здесь пока не внесены.","application":"Проверить действующую редакцию и точные пункты перед автоматизацией.","sourceUrl":"https://protect.gost.ru/gost/details/94160176-3252-4e7d-8534-2d172e6aa0de","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
INSERT INTO "normative" ("key", "revision", "payload_json", "updated_at") VALUES ('gost-r-52290-2024', 1, '{"id":"gost-r-52290-2024","documentCode":"ГОСТ Р 52290-2024","edition":"2024","clause":"Группы и технические требования к знакам","description":"Источник для будущего каталога знаков; изображения и полный текст в приложение не включены.","application":"Проверить применимые пункты и права на графику перед публикацией каталога.","sourceUrl":"https://protect.gost.ru/gost/details/39b75217-29bd-492b-94f4-c0dccb72b299","reviewStatus":"needs-review","checkedAt":"","reviewer":""}', '2026-09-26T12:00:00.000Z');
